import React, { useState, useEffect } from 'react';
import { Link, useNavigate } from 'react-router-dom';

const Results = () => {
  const [recommendations, setRecommendations] = useState(null);
  const [loading, setLoading] = useState(true);
  const navigate = useNavigate();

  useEffect(() => {
    // Get the temporary result generated by SymptomInput
    const data = JSON.parse(localStorage.getItem('recommendations') || 'null');
    window.scrollTo(0, 0);
    
    if (data) {
       setTimeout(() => {
          setRecommendations(data);
          setLoading(false);
       }, 1000);
    } else {
       setLoading(false);
    }
  }, []);

  // ===== SAVE FUNCTION =====
  const handleSaveToDashboard = () => {
    if (!recommendations) return;

    // 1. Get existing history or start empty array
    const existingHistory = JSON.parse(localStorage.getItem('ayur_history') || '[]');
    
    // 2. Create a new record with a timestamp
    const newRecord = {
      id: Date.now(), // Unique ID
      date: new Date().toLocaleDateString('en-US', { year: 'numeric', month: 'short', day: 'numeric' }),
      timestamp: new Date().toISOString(),
      ...recommendations // Spread the recommendation data
    };

    // 3. Add to history (newest first)
    const updatedHistory = [newRecord, ...existingHistory];
    
    // 4. Save back to localStorage
    localStorage.setItem('ayur_history', JSON.stringify(updatedHistory));

    // 5. Go to Dashboard
    navigate('/dashboard');
  };

  if (loading) {
    return (
      <div className="min-h-screen pt-28 pb-20 px-6 flex flex-col items-center justify-center bg-slate-50 font-sans">
        <div className="relative">
           <div className="w-20 h-20 bg-blue-100 rounded-full flex items-center justify-center animate-pulse">
              <span className="text-4xl">🧘</span>
           </div>
           <div className="absolute inset-0 border-4 border-blue-500/30 border-t-blue-600 rounded-full animate-spin"></div>
        </div>
        <h2 className="mt-8 text-2xl font-bold text-slate-800 font-serif">Generating Health Plan...</h2>
        <p className="text-slate-500 mt-2">Analyzing Dosha imbalances and selecting remedies.</p>
      </div>
    );
  }

  if (!recommendations) {
    return (
      <div className="min-h-screen pt-28 pb-20 px-6 flex flex-col items-center justify-center bg-slate-50 font-sans">
        <div className="bg-white p-10 rounded-[2rem] shadow-xl text-center max-w-md border border-slate-100">
          <h1 className="text-3xl font-bold text-slate-800 mb-4 font-serif">No Results Found</h1>
          <Link to="/symptoms" className="inline-flex items-center justify-center px-8 py-3.5 bg-blue-600 text-white font-bold rounded-xl shadow-lg hover:bg-blue-700 transition-all">
            Start New Assessment
          </Link>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen pt-28 pb-20 px-6 bg-slate-50 font-sans selection:bg-blue-100 selection:text-blue-900">
      <div className="max-w-5xl mx-auto relative z-10">
        
        {/* Header */}
        <div className="text-center mb-12">
           <div className="inline-flex items-center gap-2 px-4 py-2 rounded-full bg-white border border-blue-100 shadow-sm mb-6">
              <span className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse"></span>
              <span className="text-slate-600 font-semibold text-xs uppercase tracking-wider">Analysis Complete</span>
           </div>
           <h1 className="text-4xl md:text-5xl font-bold text-slate-900 mb-4 font-serif">Your Wellness Plan</h1>
        </div>

        {/* Summary Cards */}
        <div className="grid md:grid-cols-2 gap-6 mb-10">
           <div className="bg-white/80 backdrop-blur-xl border border-white/60 shadow-lg rounded-[2rem] p-8 flex items-center gap-6 relative overflow-hidden">
              <div className="w-16 h-16 bg-blue-600 rounded-2xl flex items-center justify-center text-3xl text-white relative z-10">⚖️</div>
              <div className="relative z-10">
                 <p className="text-slate-500 text-xs font-bold uppercase tracking-wider mb-1">Detected Imbalance</p>
                 <h2 className="text-3xl font-bold text-slate-800">{recommendations.doshaImbalance}</h2>
              </div>
           </div>
           <div className="bg-white/80 backdrop-blur-xl border border-white/60 shadow-lg rounded-[2rem] p-8 flex items-center gap-6 relative overflow-hidden">
              <div className={`w-16 h-16 rounded-2xl flex items-center justify-center text-3xl text-white relative z-10 ${
                 recommendations.severityLevel === 'severe' ? 'bg-rose-500' : 'bg-amber-500'
              }`}>📉</div>
              <div className="relative z-10">
                 <p className="text-slate-500 text-xs font-bold uppercase tracking-wider mb-1">Severity</p>
                 <h2 className="text-3xl font-bold text-slate-800 capitalize">{recommendations.severityLevel}</h2>
              </div>
           </div>
        </div>

        {/* Recommendations */}
        <div className="grid lg:grid-cols-3 gap-6 mb-12">
             {recommendations.recommendations.map((rec, index) => (
               <div key={index} className="bg-white rounded-[2rem] p-6 shadow-sm border border-slate-100 flex flex-col">
                 <div className="flex items-center gap-4 mb-4 pb-4 border-b border-slate-50">
                    <div className="w-10 h-10 bg-blue-50 text-blue-600 rounded-xl flex items-center justify-center font-bold uppercase">{rec.symptom.charAt(0)}</div>
                    <h4 className="text-lg font-bold text-slate-800 capitalize">{rec.symptom.replace('_', ' ')}</h4>
                 </div>
                 <div className="space-y-4 flex-1">
                    {rec.home && (
                       <div><p className="text-xs font-bold text-slate-400 uppercase">Home Remedy</p><p className="text-slate-700 text-sm">{rec.home}</p></div>
                    )}
                    {rec.med && (
                       <div><p className="text-xs font-bold text-slate-400 uppercase">Medicine</p><p className="text-slate-700 text-sm">{rec.med}</p></div>
                    )}
                 </div>
               </div>
             ))}
        </div>

        {/* Action Buttons with SAVE Logic */}
        <div className="mt-10 flex flex-col sm:flex-row items-center justify-center gap-4">
           <button 
              onClick={handleSaveToDashboard}
              className="w-full sm:w-auto px-10 py-4 bg-slate-900 text-white font-bold rounded-xl shadow-lg hover:bg-slate-800 hover:scale-[1.02] transition-all"
           >
              Save to Dashboard
           </button>
           <Link 
              to="/symptoms" 
              className="w-full sm:w-auto px-10 py-4 bg-white border border-slate-200 text-slate-700 font-bold rounded-xl hover:bg-slate-50 transition-all text-center"
           >
              Retake Assessment
           </Link>
        </div>

      </div>
    </div>
  );
};

export default Results;